311	// Private helpers
312	// ---------------------------------------------------------------------------
313	
314	/** Returns the final path segment (filename or folder name). */
315	function _orchBasename(path) {
316	  var parts = String(path).replace(/\\/g, '/').split('/');
317	  return parts[parts.length - 1] || path;
318	}
319	
320	/** Human-readable label for an effectiveStatus value. */
321	function _orchStatusLabel(status) {
322	  if (status === 'started') return 'Started';
323	  if (status === 'dead')    return 'Dead';
324	  return 'Pending';
325	}
326	
327	/** Formats elapsed time from an ISO start timestamp. */
328	function _orchElapsed(startedAt) {
329	  if (!startedAt) return '—';
