335	    var mins = Math.floor(secs / 60);
336	    if (mins < 60)  return mins + 'm ' + (secs % 60) + 's';
337	    return Math.floor(mins / 60) + 'h ' + (mins % 60) + 'm';
338	  } catch (_) {
339	    return '—';
340	  }
341	}

