154	        window.alert(
155	          'Failed to dismiss entry: ' +
156	          ((err && err.message) || String(err))
157	        );
158	      });
159	    });
160	
161	    return btn;
162	  }
163	
164	  // ------------------------------------------------------------------
165	  // renderLogPreview(container, slug, filename) → cleanup()
166	  // ------------------------------------------------------------------
167	
168	  /**
169	   * Starts auto-polling the run log for a queue entry and appends new
170	   * JSONL events to `container` as they arrive.
171	   *
172	   * Polling begins immediately (one fetch on call), then repeats every
173	   * 3 seconds.  Only events after the last seen line are appended.
174	   *
175	   * @param {HTMLElement} container - The element to append log entries to.
176	   * @param {string}      slug      - Project slug used for the API call.
177	   * @param {string}      filename  - JSONL log filename.
178	   * @returns {Function} cleanup — call to stop polling and clear the interval.
179	   */
180	  function renderLogPreview(container, slug, filename) {
181	    var afterLine  = 0;
182	    var stopped    = false;
183	    var intervalId = null;
184	
185	    function fetchEntries() {
186	      if (stopped) return;
187	      API.getRunLogEntries(slug, filename, afterLine).then(function (data) {
188	        if (stopped) return;
189	        var entries    = (data && Array.isArray(data.entries)) ? data.entries : [];
190	        var totalLines = (data && typeof data.totalLines === 'number')
191	          ? data.totalLines
192	          : afterLine;
193	
194	        entries.forEach(function (entry) {
195	          var div = document.createElement('div');
196	          div.className = 'log-preview-entry';
197	          var action = (entry && entry.action) ? String(entry.action) : '';
198	          div.textContent = action || JSON.stringify(entry);
199	          container.appendChild(div);
200	        });
201	
202	        afterLine = totalLines;
203	      }).catch(function () {
204	        // Polling is best-effort — swallow errors silently.
205	      });
206	    }
207	
208	    fetchEntries();
209	    intervalId = setInterval(fetchEntries, 3000);
210	
211	    return function cleanup() {
212	      stopped = true;
213	      if (intervalId !== null) {
214	        clearInterval(intervalId);
215	        intervalId = null;
216	      }
217	    };
218	  }
219	
220	  // ------------------------------------------------------------------
221	  // renderProgressBadge(lastAction) → string (HTML)
222	  // ------------------------------------------------------------------
223	
224	  var PROGRESS_BADGE_MAP = {
225	    'run_start':         { icon: '▶', color: 'info'    },
226	    'stage_start':       { icon: '⟳', color: 'info'    },
227	    'stage_complete':    { icon: '✓', color: 'success' },
228	    'wp_complete':       { icon: '✓', color: 'success' },
229	    'progress_snapshot': { icon: '◎', color: 'info'    },
230	    'run_end':           { icon: '■', color: 'neutral'  },
231	    'run_error':         { icon: '✗', color: 'error'   },
232	    'signal_shutdown':   { icon: '⚡', color: 'warning' },
233	    'stage_error':       { icon: '✗', color: 'error'   },
234	    // NOTE: resolveProgress() never surfaces heartbeat as lastAction — kept for completeness.
235	    'heartbeat':         { icon: '♥', color: 'neutral'  },
236	  };
237	
238	  /**
239	   * Renders a small badge HTML string for a JSONL action type.
240	   *
241	   * @param {string|null|undefined} lastAction - The last JSONL `action` field.
242	   * @returns {string} HTML badge string.
243	   */
244	  function renderProgressBadge(lastAction) {
245	    var mapping = (lastAction && PROGRESS_BADGE_MAP[lastAction])
246	      || { icon: '•', color: 'neutral' };
247	    var label = lastAction ? escapeHtml(String(lastAction)) : 'idle';
248	    return '<span class="badge badge-' + escapeHtml(mapping.color) + '">' +
249	      mapping.icon + ' ' + label + '</span>';
250	  }
251	
252	  // ------------------------------------------------------------------
253	  // renderCliReference() → string (HTML)
254	  // ------------------------------------------------------------------
255	
256	  /**
257	   * Returns a static HTML block with the most useful CLI commands for
258	   * managing orchestrator runs from the terminal.
259	   *
260	   * MAINTENANCE NOTE: The command text below mirrors the actual CLI surface.
261	   * Keep in sync with:
262	   *   - orchestrate binary: orchestrator/src/cli.py (CLI flags)
263	   *   - kill script:        scripts/kill-orchestrator.js
264	   *   - preflight script:   scripts/preflight-orchestrator.js (via scripts/cli.js)
265	   *
266	   * @returns {string} HTML string.
267	   */
268	  function renderCliReference() {
269	    return '<div class="orchestrator-cli-reference">' +
270	      '<h4>CLI Commands</h4>' +
271	      '<pre><code>' +
272	      '# Start a run\n' +
273	      'orchestrate &lt;plan-path&gt;\n\n' +
274	      '# Resume an interrupted run\n' +
275	      'orchestrate &lt;plan-path&gt; --resume &lt;thread-id&gt;\n\n' +
276	      '# Dry run (inspect routing without executing agents)\n' +
277	      'orchestrate &lt;plan-path&gt; --dry-run\n\n' +
278	      '# Kill stale orchestrator processes\n' +
279	      'node scripts/kill-orchestrator.js\n\n' +
280	      '# Pre-flight readiness check\n' +
281	      'node scripts/cli.js preflight --plan &lt;plan-path&gt;' +
282	      '</code></pre>' +
283	      '</div>';
284	  }
285	
286	  // ------------------------------------------------------------------
287	  // Public namespace
288	  // ------------------------------------------------------------------
289	
290	  return {
291	    renderStatusCard:    renderStatusCard,
292	    renderKillButton:    renderKillButton,
293	    renderDismissButton: renderDismissButton,
294	    renderLogPreview:    renderLogPreview,
295	    renderProgressBadge: renderProgressBadge,
296	    renderCliReference:  renderCliReference,
