37	}
38	
39	async function writeJsonlLog(
40	  logsDir: string,
41	  prefix: string,
42	  slug: string,
43	  entries: unknown[],
44	): Promise<string> {
45	  const filename = `${prefix}-${slug}.jsonl`;
