50	
51	/** Assert the shape of an empty / no-activity resolution. */
52	function expectEmpty(result: ProgressResolution): void {
53	  expect(result.summary).toBeNull();
54	  expect(result.lastAction).toBeNull();
55	  expect(result.hasStageActivity).toBe(false);
56	}
